{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib had an absolute oral bioavailability of 14.9% after a 10 mg oral dose versus i.v., below the 20% threshold; this high-transfer analogue supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "9-Nitrocamptothecin showed very low absolute oral bioavailability in patients with high variability; as a high-transfer rigid polycyclic lactone, it supports poor oral absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Hydroxysafflor yellow A, a highly polar polyhydroxylated glycoside, had low oral bioavailability in healthy volunteers; its high polarity and hydrogen-bonding burden mirror the query's physicochemical liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Baicalin, a flavonoid glucuronide, showed poor oral bioavailability in healthy subjects; this high-transfer polar glycoside/lactone analogue supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Artemisinin, a polycyclic lactone endoperoxide, is reported to have low oral bioavailability in humans; despite moderate transfer, it reinforces the pattern of poor oral absorption for rigid polycyclic lactones.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Oral idarubicin in cancer patients had a median bioavailability of 29%, above the 20% threshold, providing a contradictory example that polar glycosidic natural products can achieve F≥20%; however, its very low transfer score limits weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar, rigid polycyclic lactone with very low predicted logD and high TPSA/HBA, consistent with poor passive permeability. The highest-transfer experimental analogues—5-hydroxyrofecoxib (F≈14-15%), 9-nitrocamptothecin (very low), HSYA (low), baicalin (poor), and artemisinin (low)—all fall below or near the 20% threshold. Low-transfer examples with higher F (idarubicin ~29%, nucleosides) do not outweigh this consistent high-transfer evidence. Therefore predict low F (<20%).",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data are available for the query molecule.",
    "No permeability, solubility, or metabolism measurements exist for the query.",
    "The mechanistic basis of low F in the high-transfer analogues (e.g., efflux, first-pass metabolism) is not established for the query.",
    "Some high-transfer analogues are not structurally close to the query, so extrapolation relies on shared polarity, rigidity, and lactone features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

